scripts.script:
def run = { List cmd ->
    def proc = cmd.execute()
    proc.consumeProcessOutput(System.out, System.err)
    proc.waitFor()
    if (proc.exitValue() != 0) throw new RuntimeException("Command failed: ${cmd.join(' ')}")
}

// Ensure local registry is running
def registryStart = "docker start registry".execute()
registryStart.waitFor()
if (registryStart.exitValue() != 0) {
    run(["docker", "run", "-d", "-p", "5000:5000", "--name", "registry", "registry:2"])
}

// On Docker Desktop (Windows/Mac) the buildx container cannot reach
// localhost:5000 on the host, so use host.docker.internal instead.
// On Linux we add --driver-opt network=host so localhost resolves correctly.
def isDockerDesktop = System.getProperty("os.name").toLowerCase().contains("win") ||
                      System.getProperty("os.name").toLowerCase().contains("mac")
def registryHost = isDockerDesktop ? "host.docker.internal" : "localhost"

// Write buildkitd config so the builder treats the local registry as plain HTTP
def buildkitConfig = new File(project.basedir, "buildkitd.toml")
buildkitConfig.text = "[registry.\"${registryHost}:5000\"]\n  http = true\n  insecure = true\n"

// Ensure multiarch builder exists
def builderUse = "docker buildx use multiarch".execute()
builderUse.waitFor()
if (builderUse.exitValue() != 0) {
    def createCmd = ["docker", "buildx", "create", "--name", "multiarch", "--driver", "docker-container", "--use", "--config", buildkitConfig.absolutePath]
    if (!isDockerDesktop) createCmd += ["--driver-opt", "network=host"]
    run(createCmd)
}
buildkitConfig.delete()

// Install binfmt for cross-platform emulation
run(["docker", "run", "--rm", "--privileged", "tonistiigi/binfmt", "--install", "all"])

// Build and push to local registry
run(["docker", "buildx", "build",
    "--platform", "linux/amd64,linux/arm64",
    "--push",
    "-t", "${registryHost}:5000/kannich:${project.version}",
    project.basedir.toString()])

// Clean up build context
new File(project.basedir, "kannich-cli.jar").delete()
